import { cleanCueText } from './clean';
import type { Cue } from './types';

interface Json3Segment {
  utf8?: string;
}

interface Json3Event {
  tStartMs?: number;
  dDurationMs?: number;
  aAppend?: number;
  segs?: Json3Segment[];
}

/**
 * Parses YouTube's "json3" timed-text format.
 *
 * Auto-generated (speech recognition) tracks are rolling captions: each event
 * stays on screen until two events later, and some events only append a line
 * break. We drop the append-only events and clip every cue at the start of the
 * next one, so at most one line is active at a time.
 */
export function parseYouTubeJson3(data: unknown, options: { autoGenerated?: boolean } = {}): Cue[] {
  const events = (data as { events?: unknown } | null)?.events;
  if (!Array.isArray(events)) return [];

  const cues: Cue[] = [];
  for (const event of events as Json3Event[]) {
    if (!event || event.aAppend || !Array.isArray(event.segs)) continue;
    if (typeof event.tStartMs !== 'number') continue;

    let text = cleanCueText(event.segs.map((seg) => seg?.utf8 ?? '').join(''));
    if (options.autoGenerated) text = text.replace(/\n/g, ' ');
    if (!text) continue;

    const start = event.tStartMs / 1000;
    const end = (event.tStartMs + (event.dDurationMs ?? 0)) / 1000;
    cues.push({ start, end: Math.max(end, start), text });
  }

  cues.sort((a, b) => a.start - b.start);
  if (options.autoGenerated) {
    clipOverlaps(cues, Infinity);
    return cues;
  }
  clipOverlaps(cues, SMALL_OVERLAP);
  return mergeOverlaps(cues);
}

/** Overlaps up to this many seconds are timing slop, not lines meant to be on screen together. */
const SMALL_OVERLAP = 0.5;

/** Ends each cue where the next one starts, if they overlap by at most `limit` seconds. */
function clipOverlaps(cues: Cue[], limit: number): void {
  for (let i = 0; i < cues.length - 1; i++) {
    const cue = cues[i]!;
    const next = cues[i + 1]!;
    if (cue.end > next.start && cue.end - next.start <= limit) cue.end = Math.max(cue.start, next.start);
  }
}

/**
 * Manual tracks can show several events at once, e.g. one row in a window at the top and another at
 * the bottom, or a line that stays while a second one appears under it. Shows those as one cue per
 * stretch of time with all their rows, so a row never hides the ones still on screen.
 */
function mergeOverlaps(cues: Cue[]): Cue[] {
  const times = [...new Set(cues.flatMap((cue) => [cue.start, cue.end]))].sort((a, b) => a - b);
  const merged: Cue[] = [];
  let first = 0;
  for (let i = 0; i < times.length - 1; i++) {
    const start = times[i]!;
    const end = times[i + 1]!;
    while (first < cues.length && cues[first]!.end <= start) first++;
    const rows: string[] = [];
    for (let j = first; j < cues.length && cues[j]!.start <= start; j++) {
      if (cues[j]!.end >= end) rows.push(cues[j]!.text);
    }
    if (rows.length === 0) continue;
    const text = rows.join('\n');
    const previous = merged[merged.length - 1];
    if (previous && previous.text === text && previous.end === start) previous.end = end;
    else merged.push({ start, end, text });
  }
  return merged;
}
